import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';
import { Item } from './item.model';

@Injectable({ providedIn: 'root' })
export class ItemsService {
  constructor() {}

  getItems(): Observable<Item[]> {
    return this.http.get<Item[]>('/api/items');
  }
}

ngOnInit() {
  this.itemsService.getItems().subscribe(
    error => console.error('Error al cargar items', error),
    items => this.items = items
  );
}

candidates.expected_answer:
Los argumentos de `subscribe` van en orden: primero el callback de éxito (next) y después el de error. Aquí están intercambiados, de modo que la lista se asigna solo si la petición falla. La versión correcta es:

ngOnInit() {
  this.itemsService.getItems().subscribe(
    items => this.items = items,
    error => console.error('Error al cargar items', error)
  );
}

